import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.Connection;
import net.minecraft.network.chat.Component;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.util.Mth;
import net.minecraft.util.RandomSource;
import net.minecraft.world.ContainerHelper;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.inventory.AbstractContainerMenu;
import net.minecraft.world.item.ItemStack;

import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.BaseContainerBlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.Vec3;

public class AltarOfAbyss_Block_Entity extends BaseContainerBlockEntity {

    public int tickCount;
    private static final int NUM_SLOTS = 1;
    private NonNullList<ItemStack> stacks = NonNullList.withSize(NUM_SLOTS, ItemStack.EMPTY);
    public boolean summoningthis = false;
    public int summoningticks = 0;
    private float chompProgress;
    private float prevChompProgress;
    private final RandomSource rnd = RandomSource.create();

    public AltarOfAbyss_Block_Entity(BlockPos pos, BlockState state) {
        super(ModTileentites.ALTAR_OF_ABYSS.get(), pos, state);
    }

    public static void commonTick(Level level, BlockPos pos, BlockState state, AltarOfAbyss_Block_Entity entity) {
        entity.tick(level,state,pos);

    }

    public void tick(Level level, BlockState state, BlockPos pos) {
        tickCount++;
        summoningthis = false;
        prevChompProgress = chompProgress;
        if (!this.getItem(0).isEmpty()) {
            if(this.getItem(0).getItem() == ModItems.ABYSSAL_SACRIFICE.get()){
                summoningthis = true;
                if(summoningticks == 1) {
                    ScreenShake_Entity.ScreenShake(level, Vec3.atCenterOf(pos), 20, 0.03f, 0, 150);
                    //   this.level.addFreshEntity(new Flame_Strike_Entity(this.level, this.getBlockPos().getX() + 0.5F, this.getBlockPos().getY(), this.getBlockPos().getZ() + 0.5F, 0, 0, 100, 0, 2.5F, false, null));
                }
                if(summoningticks > 118 && summoningticks < 121) {
                    Sphereparticle(level,3,3);
                }
                if(summoningticks > 121) {
                    BlockBreaking(3, 6, 3);
                    The_Leviathan_Entity leviathan = ModEntities.THE_LEVIATHAN.get().create(level);
                    if (level instanceof ServerLevel serverLevel) {
                        if (leviathan != null) {
                            leviathan.setPos(pos.getX() + 0.5F, pos.getY() + 3, pos.getZ() + 0.5F);
                            leviathan.setHomePos(GlobalPos.of(serverLevel.dimension(), pos));
                            boolean flag = level.addFreshEntity(leviathan);
                            if (flag) {
                                this.setItem(0, ItemStack.EMPTY);
                                this.setChanged();
                                level.sendBlockUpdated(pos, state, state, Block.UPDATE_ALL);
                            }


                        }
                    }
                }

            }
        }

        if(summoningthis && chompProgress < 30F){
            chompProgress++;
        }
        if(!summoningthis && chompProgress > 0F){
            chompProgress--;
        }

        if(!summoningthis){
            summoningticks = 0;
        }else{
            summoningticks++;
        }
    }

    public float getChompProgress(float partialTick){
        return prevChompProgress + (chompProgress - prevChompProgress) * partialTick;
    }

    private void BlockBreaking(int x, int y, int z) {
        //this.level.destroyBlock(pos, false);
        int MthX = Mth.floor(this.getBlockPos().getX());
        int MthY = Mth.floor(this.getBlockPos().getY());
        int MthZ = Mth.floor(this.getBlockPos().getZ());
        for (int k2 = -x; k2 <= x; ++k2) {
            for (int l2 = -z; l2 <= z; ++l2) {
                for (int j = 0; j <= y; ++j) {
                    int i3 = MthX + k2;
                    int k = MthY + j;
                    int l = MthZ + l2;
                    BlockPos blockpos = new BlockPos(i3, k, l);
                    BlockState block = this.level.getBlockState(blockpos);
                    if (block != Blocks.AIR.defaultBlockState() && !block.is(ModTag.ALTAR_DESTROY_IMMUNE)) {
                        this.level.destroyBlock(blockpos, false);
                    }

                }
            }
        }
    }


    private void Sphereparticle(Level level,float height, float size) {
        double d0 = this.getBlockPos().getX() + 0.5F;
        double d1 = this.getBlockPos().getY() + height;
        double d2 = this.getBlockPos().getZ() + 0.5F;
        for (float i = -size; i <= size; ++i) {
            for (float j = -size; j <= size; ++j) {
                for (float k = -size; k <= size; ++k) {
                    double d3 = (double) j + (this.rnd.nextDouble() - this.rnd.nextDouble()) * 0.5D;
                    double d4 = (double) i + (this.rnd.nextDouble() - this.rnd.nextDouble()) * 0.5D;
                    double d5 = (double) k + (this.rnd.nextDouble() - this.rnd.nextDouble()) * 0.5D;
                    double d6 = (double) Mth.sqrt((float) (d3 * d3 + d4 * d4 + d5 * d5)) / 0.5 + this.rnd.nextGaussian() * 0.05D;

                    level.addParticle(ParticleTypes.REVERSE_PORTAL, d0, d1, d2, d3 / d6, d4 / d6, d5 / d6);

                    if (i != -size && i != size && j != -size && j != size) {
                        k += size * 2 - 1;

                    }
                }
            }
        }
    }

    @Override
    public int getContainerSize() {
        return this.stacks.size();
    }

    @Override
    public ItemStack getItem(int index) {
        return this.stacks.get(index);
    }

    @Override
    public ItemStack removeItem(int index, int count) {
        if (!this.stacks.get(index).isEmpty()) {
            ItemStack itemstack;

            if (this.stacks.get(index).getCount() <= count) {
                itemstack = this.stacks.get(index);
                this.stacks.set(index, ItemStack.EMPTY);
            } else {
                itemstack = this.stacks.get(index).split(count);

                if (this.stacks.get(index).isEmpty()) {
                    this.stacks.set(index, ItemStack.EMPTY);
                }

            }
            return itemstack;
        } else {
            return ItemStack.EMPTY;
        }
    }

    @Override
    public void setItem(int index, ItemStack stack) {
        boolean flag = !stack.isEmpty() && ItemStack.isSameItemSameTags(stack, this.stacks.get(index));
        this.stacks.set(index, stack);
        if (!stack.isEmpty() && stack.getCount() > this.getMaxStackSize()) {
            stack.setCount(this.getMaxStackSize());
        }
        this.saveAdditional(this.getUpdateTag());
        if (!level.isClientSide) {
            Cataclysm.sendMSGToAll(new MessageUpdateblockentity(this.getBlockPos().asLong(), stacks.get(0)));
        }
    }

    @Override
    public void load(CompoundTag compound) {
        super.load(compound);
        this.stacks = NonNullList.withSize(this.getContainerSize(), ItemStack.EMPTY);
        this.summoningthis = compound.getBoolean("Summoningthis");
        ContainerHelper.loadAllItems(compound, this.stacks);
    }

    @Override
    public void saveAdditional(CompoundTag compound) {
        super.saveAdditional(compound);
        ContainerHelper.saveAllItems(compound, this.stacks);
        compound.putBoolean("Summoningthis", this.summoningthis);
    }

    @Override
    public void startOpen(Player player) {
    }

    @Override
    public void stopOpen(Player player) {
    }



    @Override
    public int getMaxStackSize() {
        return 1;
    }

    @Override
    public boolean stillValid(Player player) {
        return true;
    }

    @Override
    public void clearContent() {
        this.stacks.clear();
    }

    @Override
    public boolean hasCustomName() {
        return false;
    }

    @Override
    public boolean canPlaceItem(int index, ItemStack stack) {
        return true;
    }

    @Override
    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    @Override
    public void onDataPacket(Connection net, ClientboundBlockEntityDataPacket packet) {
        if (packet != null && packet.getTag() != null) {
            this.stacks = NonNullList.withSize(this.getContainerSize(), ItemStack.EMPTY);
            ContainerHelper.loadAllItems(packet.getTag(), this.stacks);
        }
    }

    public CompoundTag getUpdateTag() {
        return this.saveWithoutMetadata();
    }

    @Override
    public ItemStack removeItemNoUpdate(int index) {
        ItemStack lvt_2_1_ = this.stacks.get(index);
        if (lvt_2_1_.isEmpty()) {
            return ItemStack.EMPTY;
        } else {
            this.stacks.set(index, ItemStack.EMPTY);
            return lvt_2_1_;
        }
    }

    @Override
    public Component getDisplayName() {
        return getDefaultName();
    }

    @Override
    protected Component getDefaultName() {
        return Component.translatable("block.cataclysm.altar_of_abyss");
    }

    @Override
    protected AbstractContainerMenu createMenu(int id, Inventory player) {
        return null;
    }

    @Override
    public boolean isEmpty() {
        for (int i = 0; i < this.getContainerSize(); i++) {
            if (!this.getItem(i).isEmpty()) {
                return false;
            }
        }
        return true;
    }
}

package com.github.L_Ender.cataclysm.blockentities;

import com.github.L_Ender.cataclysm.Cataclysm;
import com.github.L_Ender.cataclysm.crafting.AltarOfAmethystRecipe;
import com.github.L_Ender.cataclysm.init.ModRecipeTypes;
import com.github.L_Ender.cataclysm.init.ModTileentites;
import com.github.L_Ender.cataclysm.message.MessageUpdateblockentity;
import net.minecraft.core.BlockPos;
import net.minecraft.core.NonNullList;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.world.Clearable;
import net.minecraft.world.Container;
import net.minecraft.world.ContainerHelper;
import net.minecraft.world.SimpleContainer;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.crafting.RecipeManager;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import java.util.Optional;

public class AltarOfAmethyst_Block_Entity extends BlockEntity implements Clearable {
    private static final int NUM_SLOTS = 1;
    private final NonNullList<ItemStack> items = NonNullList.withSize(NUM_SLOTS, ItemStack.EMPTY);
    public int blessingProgress;
    public int tickCounts;
    public boolean brightThisTick = false;
    private final RecipeManager.CachedCheck<Container, AltarOfAmethystRecipe> quickCheck = RecipeManager.createCheck(ModRecipeTypes.AMETHYST_BLESS.get());

    public AltarOfAmethyst_Block_Entity(BlockPos p_155301_, BlockState p_155302_) {
        super(ModTileentites.ALTAR_OF_AMETHYST.get(), p_155301_, p_155302_);
    }

    public static void cookTick(Level p_155307_, BlockPos p_155308_, BlockState p_155309_, AltarOfAmethyst_Block_Entity p_155310_) {
        p_155310_.brightThisTick = false;
        p_155310_.tickCounts++;
        ItemStack itemstack = p_155310_.items.get(0);
        if (!itemstack.isEmpty()) {
            Container container = new SimpleContainer(itemstack);
            Optional<AltarOfAmethystRecipe> ingredient = p_155310_.quickCheck.getRecipeFor(container, p_155307_);
            ItemStack finale = ingredient.map((p_270054_) -> p_270054_.getResult().copy()).orElse(itemstack);
            if(ingredient.isPresent()){
                p_155310_.brightThisTick = true;
                if(p_155310_.blessingProgress >= ingredient.get().getTime()) {
                    ItemStack current = p_155310_.getItem(0).copy();
                    current.shrink(1);
                    if(!current.isEmpty()){
                        ItemEntity itemEntity = new ItemEntity(p_155307_, p_155308_.getX() + 0.5F, p_155308_.getY() + 0.5F, p_155308_.getZ() + 0.5F, current);
                        if(!p_155307_.isClientSide){
                            p_155307_.addFreshEntity(itemEntity);
                        }
                    }
                    p_155310_.setItem(0, finale);
                }
            }

        }

        if(!p_155310_.brightThisTick){
            p_155310_.blessingProgress = 0;
        }else{
            p_155310_.blessingProgress++;
        }

    }

    public int getContainerSize() {
        return this.items.size();
    }

    public ItemStack getItem(int index) {
        return this.items.get(index);
    }

    public void setItem(int index, ItemStack stack) {
        this.items.set(index, stack);
        if (!stack.isEmpty() && stack.getCount() > this.getMaxStackSize()) {
            stack.setCount(this.getMaxStackSize());
        }
        this.saveAdditional(this.getUpdateTag());
        if (!level.isClientSide) {
            Cataclysm.sendMSGToAll(new MessageUpdateblockentity(this.getBlockPos().asLong(), items.get(0)));
        }
    }

    public int getMaxStackSize() {
        return 1;
    }


    public NonNullList<ItemStack> getItems() {
        return this.items;
    }

    public void load(CompoundTag p_155312_) {
        super.load(p_155312_);
        this.items.clear();
        ContainerHelper.loadAllItems(p_155312_, this.items);
        if (p_155312_.contains("blessingProgress", 11)) {
            this.blessingProgress = p_155312_.getInt("blessingProgress");
        }

    }

    protected void saveAdditional(CompoundTag p_187486_) {
        super.saveAdditional(p_187486_);
        ContainerHelper.saveAllItems(p_187486_, this.items, true);
        p_187486_.putInt("blessingProgress", this.blessingProgress);
    }

    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    public CompoundTag getUpdateTag() {
        CompoundTag compoundtag = new CompoundTag();
        ContainerHelper.saveAllItems(compoundtag, this.items, true);
        return compoundtag;
    }

    public Optional<AltarOfAmethystRecipe> getCookableRecipe(ItemStack p_59052_) {
        return this.items.stream().noneMatch(ItemStack::isEmpty) ? Optional.empty() : this.quickCheck.getRecipeFor(new SimpleContainer(p_59052_), this.level);
    }

    @Override
    public void clearContent() {
        this.items.clear();
    }
}

package com.github.L_Ender.cataclysm.blockentities;

import com.github.L_Ender.cataclysm.Cataclysm;
import com.github.L_Ender.cataclysm.entity.AnimationMonster.BossMonsters.Ignis_Entity;
import com.github.L_Ender.cataclysm.entity.effect.ScreenShake_Entity;
