        double theta = (yBodyRot) * (Math.PI / 180);
        theta += Math.PI / 2;
        double vecX = Math.cos(theta);
        double vecZ = Math.sin(theta);

        int brand = this.getBossPhase() > 0 ? 240 : 200;
        if (this.getAnimation() == SWING_ATTACK) {
